    if (!isFinite(max) || max < 0.1 || max > 24 || Math.round(max * 10) !== max * 10) max = null;
    if (mode === 'capped' && max == null) mode = 'actual';
    return { mode: mode, maxHoursPerDay: mode === 'capped' ? max : null };
