      doc.write('<td class="r">$' + d.before.toFixed(2) + '</td>');
      doc.write('<td class="r">$' + (d.deducted || 0).toFixed(2) + '</td>');
      doc.write('<td class="r">$' + (d.received || 0).toFixed(2) + '</td>');
